∀ (A B C D : InternalSpace.PauliMatrix),
  (A * B * C * D).trace =
    have a := InternalSpace.pauliScalarCoefficient A;
    have b := InternalSpace.pauliScalarCoefficient B;
    have c := InternalSpace.pauliScalarCoefficient C;
    have d := InternalSpace.pauliScalarCoefficient D;
    have u := InternalSpace.pauliVectorCoefficient A;
    have v := InternalSpace.pauliVectorCoefficient B;
    have w := InternalSpace.pauliVectorCoefficient C;
    have x := InternalSpace.pauliVectorCoefficient D;
    2 *
      ((a * b + u ⬝ᵥ v) * (c * d + w ⬝ᵥ x) +
        (a • v + b • u + Complex.I • InternalSpace.pauliCross u v) ⬝ᵥ
          (c • x + d • w + Complex.I • InternalSpace.pauliCross w x))

