∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  d.vertexGraph.componentBlock (Sum.inl 0) = d.vertexGraph.componentBlock (Sum.inl 1)

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {n : ℕ}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) (τ τ' : ℝ) (σ : Fin n → ℝ),
  Function.Injective (d.externalPieceMixedPosition τ τ' σ)

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {n : ℕ}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) (τ τ' : ℝ) (σ : Fin n → ℝ),
  StrictMono (d.externalPieceMixedPosition τ τ' σ)

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {n : ℕ}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) {m : ℕ}
  (h : d.externalInteractionPart.card = m), (d.externalPieceOfCardEq h).externalLabel = d.externalLabel

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {n : ℕ}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel n Finset.univ) {m : ℕ}
  (h : d.externalInteractionPart.card = m) (v : Fin m),
  (d.externalPieceOfCardEq h).vertexLabel ⟨v, ⋯⟩ = d.vertexLabel ⟨(d.externalInteractionPart.orderEmbOfFin h) v, ⋯⟩

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  d.externalVacuumSplit.1.externalLabel = d.externalLabel

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S) (e : Fin 2),
  Sum.inl e ∈ ↑d.externalComponentPart

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  d.IsExternallyConnected ↔ SecondQuantization.Common.HasNoVacuumComponent d.vertexGraph

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  d.vertexGraph.Preconnected → d.IsExternallyConnected

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  Combinatorics.Pairing.IsSplit d.externalSlotLegSplitting d.pairing

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  SecondQuantization.Common.TwoPointDiagram.ofSlotSplit ⋯ d.externalVacuumSplit.1 d.externalVacuumSplit.2 = d

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N M : ℕ} {T : Finset (Fin N)} {U : Finset (Fin M)}
  (e : ↥T ≃ ↥U) (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T),
  (SecondQuantization.Common.TwoPointDiagram.slotCongr e d).externalLabel = d.externalLabel

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N M : ℕ} {T : Finset (Fin N)} {U : Finset (Fin M)}
  (e : ↥T ≃ ↥U) (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T),
  (SecondQuantization.Common.TwoPointDiagram.slotCongr e d).IsExternallyConnected ↔ d.IsExternallyConnected

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N M : ℕ} {T : Finset (Fin N)} {U : Finset (Fin M)}
  (e : ↥T ≃ ↥U) (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T) (v : ↥U),
  (SecondQuantization.Common.TwoPointDiagram.slotCongr e d).vertexLabel v = d.vertexLabel (e.symm v)

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S T : Finset (Fin N)} (h : T ⊆ S)
  (ext : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N T)
  (vac : SecondQuantization.Common.QuarticDiagram InternalLabel N (S \ T)) (v : ↥(S \ T)),
  have d := SecondQuantization.Common.TwoPointDiagram.ofSlotSplit h ext vac;
  have B := ⟨d.vertexGraph.componentBlock (SecondQuantization.Common.slotSplitVacuumVertex v), ⋯⟩;
  B ∈ SecondQuantization.Common.vacuumComponentParts d.vertexGraph

∀ {Config : Type u_1} {G : Type u_2} [inst : AddCommGroup G] {grading : Config → G}
  {A : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config}
  {m n k : Config} {c : ℂ} {q : G},
  A (SecondQuantization.Common.basisState n) = c • SecondQuantization.Common.basisState k →
    SecondQuantization.Common.matrixCoeff A m n ≠ 0 → grading k = grading n + q → grading m = grading n + q

∀ {Config : Type u_1}
  {A : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config}
  {m n k : Config} {c : ℂ},
  A (SecondQuantization.Common.basisState n) = c • SecondQuantization.Common.basisState k →
    SecondQuantization.Common.matrixCoeff A m n = if m = k then c else 0

∀ {Config : Type u_1}
  {A B : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config},
  (∀ (m n : Config), SecondQuantization.Common.matrixCoeff A m n = SecondQuantization.Common.matrixCoeff B m n) → A = B

∀ {External : Type u_1} {Vertex : Type u_2} [inst : DecidableEq External] [inst_1 : Fintype External]
  [inst_2 : DecidableEq Vertex] {M : Type u_3} [inst_3 : CommMonoid M] {S : Finset Vertex}
  (G : SimpleGraph (External ⊕ ↥S)) (f : ↥S → M), ∏ v, f v = ∏ B, ∏ v, f ⟨↑v, ⋯⟩

∀ {Config : Type u_1}
  (V : SecondQuantization.Common.AlgebraicFock Config →ₗ[ℂ] SecondQuantization.Common.AlgebraicFock Config)
  (n : Config), SecondQuantization.Common.reachableSupport V 0 n = {n}

∀ {Mode : Type u_1} [inst : LinearOrder Mode] (i : Mode),
  (SecondQuantization.Fermionic.create i) SecondQuantization.Fermionic.fockVacuum =
    SecondQuantization.Fermionic.basisState {i}

∀ {Mode : Type u_1} [inst : LinearOrder Mode] [inst_1 : Fintype Mode] {i : Mode}
  {n : SecondQuantization.Fermionic.Occupation Mode},
  i ∈ n → (SecondQuantization.Fermionic.finiteHilbertCreate i) (SecondQuantization.Common.finiteHilbertBasisState n) = 0

∀ {Mode : Type u_1} [inst : LinearOrder Mode] [inst_1 : Fintype Mode] {n : ℕ} {i j : Mode} {M : Type u_2}
  [inst_2 : AddCommMonoid M] (F : SecondQuantization.Fermionic.FixedExternalTwoPointWickDiagram Mode n i j → M),
  ∑ d, F d = ∑ T ∈ Finset.univ.powerset, ∑ p, F ↑((SecondQuantization.Fermionic.fixedExternalFiberEquiv T).symm p)

∀ {H : Type u_1} [inst : NormedAddCommGroup H] [inst_1 : InnerProductSpace ℂ H] [CompleteSpace H] {ι : Type u_2}
  {κ : Type u_3} (d : HilbertBasis ι ℂ H) (f : HilbertBasis κ ℂ H) (T : H →L[ℂ] H),
  ContinuousLinearMap.IsHilbertSchmidtWrt d T ↔ ContinuousLinearMap.IsHilbertSchmidtWrt f T

∀ {ι : Type u_1} {α : Type u_2} (F : ι → Type u_3) [inst : (i : ι) → Fintype (F i)] {total : ℕ}
  (ambientEquiv : α ≃ (i : ι) × F i) (order : Fin total ≃ α) (i : ι),
  (Combinatorics.familyGlobalSlots✝ F ambientEquiv order i).card = Fintype.card (F i)

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {E N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.ExternalInsertionDiagram ExternalLabel InternalLabel E N S)
  (B : ↥d.vertexGraph.componentPartition.parts), StrictMono (d.componentDiagramLeg B)

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {E N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.ExternalInsertionDiagram ExternalLabel InternalLabel E N S)
  (B : ↥d.vertexGraph.componentPartition.parts), (↑B).toLeft.card = 2 * d.externalPairCount B

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S),
  ¬d.ExternalVerticesConnected → Sum.inl 1 ∉ ↑d.externalComponentPart

∀ {ExternalLabel : Type u_1} {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.TwoPointDiagram ExternalLabel InternalLabel N S) (leg : Fin (2 * (2 * S.card + 1))),
  d.legInComponent (↑d.externalComponentPart) leg → ∃ i, d.externalSlotLegSplitting (Sum.inl i) = leg

∀ {InternalLabel : Type u_2} {N : ℕ} {S : Finset (Fin N)}
  (d : SecondQuantization.Common.QuarticDiagram InternalLabel N S) (C : ↥d.vertexGraph.componentPartitionOn.parts),
  d.vertexGraph.componentBlockOn (SecondQuantization.Common.QuarticDiagram.componentRepresentative✝ d C) = ↑C

∀ {Mode : Type u_1} {i j : Mode} {m k : ℕ} (shuffle : Combinatorics.SlotShuffle m k)
  (ext : { d // SecondQuantization.Common.TwoPointDiagram.IsExternallyConnected ↑d })
  (x : SecondQuantization.Common.OrderedQuarticDiagramData (SecondQuantization.Common.QuarticVertexLabel Mode) k),
  have p := (SecondQuantization.Fermionic.fixedExternalShuffleFiberDataEquiv shuffle).symm (ext, x);
  have d := (SecondQuantization.Fermionic.fixedExternalFiberEquiv shuffle.leftSlots).symm p;
  have hsize := ⋯;
  (↑d).externalPieceOfCardEq hsize = ↑ext

∀ {Mode : Type u_1} {i j : Mode} {m k : ℕ} (shuffle : Combinatorics.SlotShuffle m k)
  (ext : { d // SecondQuantization.Common.TwoPointDiagram.IsExternallyConnected ↑d })
  (x : SecondQuantization.Common.OrderedQuarticDiagramData (SecondQuantization.Common.QuarticVertexLabel Mode) k)
  (σ : Fin (m + k) → ℝ),
  have p := (SecondQuantization.Fermionic.fixedExternalShuffleFiberDataEquiv shuffle).symm (ext, x);
  have d := (SecondQuantization.Fermionic.fixedExternalFiberEquiv shuffle.leftSlots).symm p;
  have hsize := ⋯;
  SecondQuantization.Common.TwoPointDiagram.externalPieceTimesOfCardEq (↑↑d) hsize σ = fun q =>
    σ (shuffle.slotEquiv (Sum.inl q))
